  let L = 0, m = 1;
  for (let k = 0; k < n; k++) {
    let d = s[k];
    for (let i = 1; i <= L; i++) if (C[i]) d ^= s[k - i];
    if (d === 0) {
      m += 1;
    } else if (2 * L <= k) {
      T.set(C.subarray(0, L + 1));
      for (let i = L + 1; i <= n; i++) T[i] = 0;
      // C <- C + x^m B
      for (let i = 0; i + m <= n; i++) if (B[i]) C[i + m] ^= 1;
      const newL = k + 1 - L;
      B.set(T.subarray(0, n + 1));
      L = newL; m = 1;
    } else {
      for (let i = 0; i + m <= n; i++) if (B[i]) C[i + m] ^= 1;
