      for (let i = 0; i + m <= n; i++) if (B[i]) C[i + m] ^= 1;
      const newL = k + 1 - L;
      B.set(T.subarray(0, n + 1));
      L = newL; m = 1;
    } else {
      for (let i = 0; i + m <= n; i++) if (B[i]) C[i + m] ^= 1;
